from pathlib import Path
import re,html,json
root=Path(__file__).parent
scenes=[
('라파엘','극장의 작은 무대에서 이야기가 끝나자, 이번에는 시선이 하늘로 향했다. 별과 구름 사이에 밝은 빛이 퍼져 있었다. 이곳은 인간의 세상을 내려다보며 이야기하는 천상의 자리였다.\n그 앞에 라파엘, 가브리엘, 미카엘이 나섰다. 이들은 천사들 가운데 중요한 역할을 맡은 대천사였다. 세 천사는 각자 바라본 세계의 모습을 노래하기 시작했다.','이 넓은 세계에는 아직 우리가 다 알지 못하는 놀라움이 있어.'),
('가브리엘','라파엘은 정해진 길을 따라 움직이는 태양을 노래했다. 가브리엘은 빛과 어둠이 번갈아 찾아오는 지구와, 바위에 부딪혀 거품을 일으키는 바다를 이야기했다.\n두 천사는 세상의 모든 일을 설명할 수 있다고 말하지 않았다. 오히려 다 이해하지 못해도 놀라워할 수 있다고 느꼈다. 거대한 세계를 바라보는 일은 그들에게 두려움과 용기를 함께 주었다.','낮이 지나면 밤이 오고, 다시 아침이 찾아와. 익숙한 일인데도 참 신기하구나.'),
('미카엘','미카엘의 노래에는 폭풍과 번개가 담겼다. 바다와 육지를 가로지르는 바람은 거칠었지만, 그 뒤에는 다시 조용한 낮이 찾아왔다.\n세 천사가 함께 목소리를 냈다. 그들은 세계의 아름다움이 언제나 평온한 모습에만 있는 것은 아니라고 보았다. 자신들이 다 헤아릴 수 없는 움직임 앞에서도, 세상을 향한 믿음은 사라지지 않았다.','거친 폭풍만 보고 세상의 전부를 안다고 할 수는 없겠지.'),
('메피스토펠레스','그 자리에 메피스토펠레스가 나타났다. 그는 인간의 약점을 들추어 보고, 사람들이 더 나아질 수 있다는 믿음을 의심하는 악마였다. 천사들이 세계를 칭찬하는 동안에도 그의 관심은 고통받는 인간에게 가 있었다.\n그가 말을 건넨 상대는 주였다. 여기서 주는 이 세계를 만든 신을 부르는 말이다. 메피스토펠레스는 예의를 갖춘 말투로 인사했지만, 곧 인간을 비웃기 시작했다.','태양이 얼마나 훌륭한지는 모르겠군. 내 눈에는 인간들이 괴로워하는 모습부터 보이는데.'),
('메피스토펠레스','메피스토펠레스는 인간이 생각하는 힘을 가졌으면서도, 그 힘으로 더 나쁜 일을 한다고 주장했다. 다른 생명보다 똑똑하다고 여기면서 사소한 일에 끼어들고 스스로 문제를 만든다는 것이었다.\n그의 말에는 날카롭게 들어맞는 부분도 있었다. 하지만 인간의 잘못만 골라 보는 태도 역시 숨어 있었다. 누군가가 실수한 뒤에 무엇을 배우는지까지 그는 보려 하지 않았다.','이성이라니. 그 좋은 힘을 갖고도 왜 늘 이런 꼴일까?'),
('메피스토펠레스','주가 물었다. 늘 잘못을 찾아내는 것 말고는 할 말이 없느냐는 질문이었다. 메피스토펠레스는 지상의 형편이 여전히 나쁘다고 답했다.\n그는 자신의 말이 솔직한 관찰이라고 생각했다. 그러나 무엇을 바라볼지 먼저 고른 다음 판단한다면, 그 판단은 쉽게 한쪽으로 기울 수 있었다. 같은 인간의 삶을 두고도 두 존재는 다른 가능성을 보고 있었다.','좋은 점을 찾아 달라는 말씀인가? 그렇다고 내가 본 고통이 없어지는 건 아니지.'),
('메피스토펠레스','메피스토펠레스는 인간이 가엾어 자신조차 괴롭히고 싶지 않다고 말했다. 그때 주가 한 사람의 이름을 꺼냈다. 파우스트였다.\n파우스트는 지상에서 학문을 연구하는 박사였다. 그는 이 자리에 없었고, 자신의 이름이 오가는 줄도 몰랐다. 주가 그를 자신의 종이라고 부른 것은, 파우스트가 아직 헤매고 있더라도 그를 향한 믿음을 거두지 않았다는 뜻이었다.','파우스트 박사라. 그 사람이라면 나도 알지.'),
('메피스토펠레스','메피스토펠레스는 파우스트가 특별한 방식으로 살아간다고 말했다. 그는 하늘에서는 가장 아름다운 별을, 땅에서는 가장 큰 즐거움을 바랐다. 가까이 있는 것도 멀리 있는 것도 그를 충분히 만족시키지 못했다.\n더 알고 싶고 더 깊이 느끼고 싶은 마음은 사람을 앞으로 나아가게 한다. 하지만 아무것도 충분하지 않다고 느끼면 이미 가진 것까지 하찮게 보일 수 있다. 메피스토펠레스는 파우스트의 그런 틈을 눈여겨보고 있었다.','무엇을 얻어도 만족하지 못하는 사람. 그런 사람에게는 다음 욕심을 보여 주면 되겠군.'),
('메피스토펠레스','주는 파우스트가 지금은 어지럽게 헤매더라도 결국 길을 찾으리라고 말했다. 정원사가 푸른 어린 나무를 보며 앞으로 맺힐 꽃과 열매를 기다리는 것처럼, 아직 끝나지 않은 삶을 믿고 있었다.\n메피스토펠레스는 그 믿음에 도전했다. 자신에게 기회를 주면 파우스트를 다른 길로 이끌 수 있다는 것이었다. 대화는 한 사람의 가능성을 두고 벌이는 내기로 바뀌었다.','그 믿음이 얼마나 굳은지 한번 보지. 내가 이끌어도 끝까지 제 길을 찾을까?'),
('메피스토펠레스','메피스토펠레스는 파우스트를 조금씩 자신의 길로 데려가도 되는지 물었다. 주는 그가 지상에 살아 있는 동안 그것을 금하지 않겠다고 답했다. 인간은 무언가를 이루려고 애쓰는 동안 잘못된 길로 들어서기도 한다는 말이 이어졌다.\n그 말은 실수라면 무엇이든 괜찮다는 허락은 아니었다. 아직 끝나지 않은 사람을 한 번의 방황만으로 단정하지 않겠다는 믿음이었다. 메피스토펠레스는 허락을 얻었다는 사실에 먼저 만족했다.','좋아. 살아 있는 사람이라야 유혹할 재미도 있지.'),
('메피스토펠레스','메피스토펠레스는 고양이가 쥐를 대하듯 인간을 상대한다고 말했다. 장난스러운 표현이었지만, 다른 존재를 자기 즐거움의 대상으로 보는 태도가 드러났다.\n주는 파우스트를 근원에서 멀어지게 할 수 있다면 해 보라고 했다. 그러면서 선한 사람은 마음이 어두워져도 올바른 길을 알아볼 수 있다고 말했다. 메피스토펠레스가 확신한 약점 뒤에서, 주는 아직 남아 있는 선택의 힘을 보고 있었다.','길을 안다는 것과 그 길을 고른다는 건 다르지. 나는 그 사이를 노릴 거야.'),
('메피스토펠레스','메피스토펠레스는 오래 걸리지 않을 것이라고 자신했다. 목적을 이루면 마음껏 승리를 기뻐하게 해 달라는 말도 덧붙였다.\n그는 아직 파우스트와 마주하지도 않았지만, 벌써 이긴 뒤를 상상하고 있었다. 남의 욕심을 잘 읽는 능력이 때로는 자신의 자신감까지 지나치게 키울 수 있었다. 그는 그 가능성을 돌아보지 않았다.','이번 내기는 걱정할 필요 없어. 그가 원하는 것을 차례로 보여 주면 되니까.'),
('메피스토펠레스','메피스토펠레스는 파우스트가 끝내 굴욕을 겪으리라고 말했다. 그러나 주는 악마의 존재 자체를 미워한다고 답하지 않았다. 인간은 쉽게 편한 자리에 머무르려 하므로, 계속 움직이게 만드는 자극도 필요하다고 설명했다.\n그렇다고 메피스토펠레스의 모든 행동이 옳다는 뜻은 아니었다. 같은 만남에서도 누군가는 무너지고, 누군가는 자신의 선택을 돌아볼 수 있었다. 이 내기의 결과는 아직 누구의 눈앞에도 일어나지 않았다.','나를 방해만 하는 존재로 보지는 않는군. 그래도 결과까지 마음에 드실지는 두고 봐야겠지.'),
('메피스토펠레스','주는 대천사들에게 살아 움직이는 세계의 아름다움을 기뻐하라고 말했다. 쉽게 바뀌는 겉모습만 보지 말고, 오래 생각하며 붙잡을 만한 뜻을 찾으라는 말이었다. 천상이 닫히자 세 천사는 흩어졌고, 메피스토펠레스만 잠시 남았다.\n그는 가끔 주를 만나는 일이 나쁘지 않다고 생각했다. 자신 같은 악마와도 말을 나누는 상대와 굳이 사이를 끊을 생각은 없었다. 가벼운 웃음이 남았지만, 그가 던진 내기는 지상에 살아 있는 한 사람을 향하고 있었다.','높으신 분이 악마에게도 이렇게 말을 걸어 주시니, 가끔 찾아뵙는 것도 괜찮군.')]
intro='<section class="adaptation-intro" lang="ko"><p class="voice-label">[나레이션: 이야기 밖에서 인물의 마음까지 알려 주는 서술자]</p><p>공연을 준비하던 사람들의 이야기가 끝나고, 이제 무대는 인간의 눈이 닿지 않는 곳으로 넓어졌다. 이곳에서 오갈 대화는 아직 지상에 있는 파우스트에게 알려지지 않았다.</p></section>'
for directory in [root,root/'dist']:
 f=directory/'chapter-03.html';s=f.read_text(encoding='utf-8');de=re.findall(r'<pre lang="de">(.*?)</pre>',s,re.S);ko=re.findall(r'<div class="ko-translation" lang="ko">(.*?)</div>',s,re.S)
 s=re.sub(r'<p class="translation-note">.*?</p>','',s,flags=re.S)
 # Close every existing aligned source/translation pair together.
 s=re.sub(r'(<pre lang="de">.*?</pre>)(<div class="ko-translation" lang="ko">.*?</div>)',r'<details class="source-fold"><summary>독일어 원문 · 한국어 번역 펼치기</summary>\1\2</details>',s,flags=re.S)
 cur=[0]
 def add(m):
  speaker,body,thought=scenes[cur[0]];cur[0]+=1
  return m[0]+'<section class="adaptation-prose" lang="ko"><p class="voice-label">[나레이션: 이야기 밖에서 인물의 마음까지 알려 주는 서술자]</p>'+''.join('<p>'+html.escape(x)+'</p>' for x in body.split('\n'))+f'<aside class="inner-voice"><p class="voice-label">[독백: {speaker}]</p><p>‘{html.escape(thought)}’</p></aside></section>'
 s=re.sub(r'<figure\b.*?</figure>',add,s,flags=re.S);assert cur[0]==14
 s=s.replace('</h1>','</h1>'+intro,1)
 css='.adaptation-prose,.adaptation-intro{font:var(--size,20px)/1.95 system-ui,sans-serif;word-break:keep-all}.adaptation-prose p,.adaptation-intro p{margin:0 0 1.2em}.voice-label{font:600 13px/1.7 system-ui;color:#80584b}.inner-voice{padding:16px 22px;background:#eee5d8;border-left:3px solid #997b68;margin:22px 0}.source-fold{margin:20px 0 42px;border:1px solid #cfc3b4;padding:12px 16px}.source-fold summary{cursor:pointer;font:14px/1.7 system-ui;color:#75604d}.source-fold pre,.source-fold .ko-translation{font-size:17px}'
 s=s.replace('</style>',css+'</style>');assert re.findall(r'<pre lang="de">(.*?)</pre>',s,re.S)==de;assert re.findall(r'<div class="ko-translation" lang="ko">(.*?)</div>',s,re.S)==ko;assert not re.search(r'<details class="source-fold"[^>]*\bopen\b',s)
 f.write_text(s,encoding='utf-8')
(root/'adaptations/chapter-03.json').write_text(json.dumps({'title':'아직 끝나지 않은 사람','persona':'K-FAUST_META_PERSONA_v1.0.md','audience':'중학생','scenes':[{'narration':b,'speaker':a,'monologue':c} for a,b,c in scenes]},ensure_ascii=False,indent=2),encoding='utf-8');print('14 narration sections, 14 named monologues; 16 source/translation pairs preserved and closed; 14 images maintained')
